mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.yz = rot(0.4) * p.yz;
  vec3 p1 = p; p1.xz = rot(time * 0.5) * p1.xz;
  vec3 p2 = p; p2.xy = rot(-time * 0.7) * p2.xy;
  float r1 = length(vec2(length(p1.xz) - 1.4, p1.y)) - 0.07;
  float r2 = length(vec2(length(p2.xz) - 0.9, p2.y)) - 0.06;
  float core = length(p) - (0.35 + 0.08 * sin(time * 3.0));
  return min(min(r1, r2), core);
}
shader_body {
