  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.03, 0.02, 0.01);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(1.5, 2.0, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 48.0);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    col = vec3(0.2, 0.12, 0.04) + diff * vec3(1.0, 0.8, 0.2) + spec * vec3(1.0, 0.95, 0.8) + rim * vec3(1.0, 0.6, 0.1);
  }
  col += glow * vec3(1.0, 0.7, 0.2) * (0.8 + 0.3 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
